#!/usr/bin/env node
/**
 * iOS counterpart of android-post-init.mjs. Run after `pnpm tauri ios init`, then run `xcodegen generate` in src-tauri/gen/apple
 * (Tauri's iOS project is generated by XcodeGen from the files in Sources/<app>/, so the new files are picked up by that step).
 *  - copies the audio-interruption observer (FIX-02) into the app's Sources folder
 * It never edits project files by hand and is safe to run twice. Not run or verified in the authoring environment.
 */
import { copyFileSync, existsSync, readdirSync, statSync } from "node:fs";
import { join } from "node:path";

const sources = join(process.cwd(), "src-tauri", "gen", "apple", "Sources");
if (!existsSync(sources)) {
  console.error("src-tauri/gen/apple/Sources not found — run `pnpm tauri ios init` first.");
  process.exit(1);
}
const app = readdirSync(sources).find((n) => statSync(join(sources, n)).isDirectory());
if (!app) {
  console.error("No app folder inside src-tauri/gen/apple/Sources.");
  process.exit(1);
}
for (const f of ["BMAudioObserver.swift", "BMAudioObserverLoader.m"]) {
  copyFileSync(join(process.cwd(), "scripts", "ios", f), join(sources, app, f));
}
console.log(`iOS audio-interruption observer added to Sources/${app}. Now run: (cd src-tauri/gen/apple && xcodegen generate)`);
